{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, a prenyl-substituted lipophilic drug, had an absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold; the isoprenoid motif is the closest structural link to the query's polyprenyl chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib, a poorly soluble methoxy-substituted drug, had an absolute oral bioavailability of only 13.9% in the fed state, illustrating solubility-limited oral absorption relevant to the highly lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Isradipine had a systemic availability of 17% in healthy volunteers, below the 20% threshold, although its low F is primarily due to first-pass metabolism rather than the query's solubility limitation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Nifedipine showed a bioavailability of 45 ± 8% in healthy volunteers, above the threshold, but this high-F evidence comes from a dihydropyridine with different absorption and metabolism characteristics and does not transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is ubiquinone-10 (coenzyme Q10), a large, highly lipophilic, practically water-insoluble polyprenyl benzoquinone. Its oral bioavailability is expected to be below 20% due to solubility/dissolution-limited absorption; the closest transferable low-F evidence (pentazocine, rigosertib fed) supports a low prediction, while high-F evidence comes from unrelated chemotypes.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for ubiquinone-10 in conventional oral formulation is provided in the evidence set.",
    "No structurally close polyprenyl quinone analog with measured F is available; transferability of the low-F evidence is limited.",
    "Formulation-dependent absorption of CoQ10 is not captured by the supplied records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

